
:root{--navy:#06284a;--navy2:#031b31;--teal:#008f8c;--mint:#5be0d4;--bg:#edf4f7;--white:#fff;--text:#203040;--muted:#66788a;--line:#dce8ee;--shadow:0 18px 50px rgba(6,40,74,.10)}
*{box-sizing:border-box;margin:0;padding:0}html{scroll-behavior:smooth}
body{font-family:"Plus Jakarta Sans",Arial,sans-serif;color:var(--text);background:radial-gradient(circle at 8% 5%,rgba(0,143,140,.06),transparent 25%),linear-gradient(180deg,#edf4f7,#f7fafb 48%,#eaf3f5);line-height:1.65}
a{text-decoration:none;color:inherit}img{display:block;max-width:100%}.container{width:min(1180px,calc(100% - 40px));margin:auto}
header{position:sticky;top:0;z-index:1000;background:rgba(255,255,255,.92);backdrop-filter:blur(18px);border-bottom:1px solid rgba(6,40,74,.08)}
.nav{min-height:84px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:inline-flex;align-items:center;gap:12px;flex:0 0 auto}.brand-label{display:flex;flex-direction:column;line-height:1.1;white-space:nowrap;color:var(--navy)}.brand-label strong{font-size:18px;font-weight:900}.brand-label>span{font-size:15px;font-weight:700;letter-spacing:.2px}.logo-mark{display:block;width:72px;height:72px;flex:0 0 72px;border-radius:50%;background:#fff url("data:image/png;base64,") center / cover no-repeat;box-shadow:0 3px 12px rgba(0,26,49,.17)}
.nav-links{display:flex;align-items:center;gap:16px;white-space:nowrap}.nav-links a{font-size:14px;font-weight:800;color:var(--navy);transition:.2s}.nav-links a:hover,.nav-links a.active{color:var(--teal)}
.nav-cta,.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;border-radius:999px;font-weight:900;transition:.25s;border:0;cursor:pointer}
.nav-cta{padding:12px 18px;background:var(--navy);color:#fff!important}.nav-cta:hover{background:var(--teal);transform:translateY(-2px)}
.menu-btn{display:none;border:0;background:none;font-size:25px;color:var(--navy)}
.hero{min-height:610px;display:flex;align-items:center;position:relative;isolation:isolate;overflow:hidden;background:linear-gradient(105deg,rgba(2,22,42,.94),rgba(5,53,78,.80) 52%,rgba(0,115,112,.68)),url("data:image/png;base64,") center/cover;color:#fff}
.hero:before{content:"";position:absolute;z-index:-1;width:520px;height:520px;border:1px solid rgba(91,224,212,.18);border-radius:50%;right:-160px;top:-180px;box-shadow:0 0 0 70px rgba(91,224,212,.025),0 0 0 140px rgba(91,224,212,.018)}
.hero-content{max-width:850px;padding:70px 0}.eyebrow{display:inline-flex;padding:9px 15px;border:1px solid rgba(91,224,212,.4);border-radius:999px;background:rgba(255,255,255,.08);font-size:12px;font-weight:900;letter-spacing:1.3px;text-transform:uppercase;margin-bottom:22px}
.hero h1{font-size:clamp(45px,6.4vw,78px);line-height:1;letter-spacing:-3px;margin-bottom:24px;text-shadow:0 8px 35px rgba(0,0,0,.2)}.hero h1 span{color:var(--mint)}
.hero p{font-size:clamp(18px,2vw,22px);max-width:730px;color:rgba(255,255,255,.86);margin-bottom:34px}.hero-buttons{display:flex;flex-wrap:wrap;gap:13px}
.btn{padding:15px 24px}.btn-primary{background:var(--teal);color:#fff;box-shadow:0 12px 30px rgba(0,143,140,.25)}.btn-primary:hover{background:#0bb7ad;transform:translateY(-3px)}.btn-light{background:#fff;color:var(--navy)}.btn-light:hover{transform:translateY(-3px);box-shadow:0 12px 30px rgba(0,0,0,.15)}
.hero-proof{display:flex;gap:28px;flex-wrap:wrap;margin-top:38px;padding-top:24px;border-top:1px solid rgba(255,255,255,.16)}.hero-proof strong{display:block;font-size:14px}.hero-proof span{display:block;color:rgba(255,255,255,.62);font-size:12px}
.section{padding:90px 0}.section.alt{background:rgba(226,239,244,.55)}.section-head{text-align:center;max-width:760px;margin:0 auto 45px}.kicker{color:var(--teal);font-size:12px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:9px}.section-head h2{font-size:clamp(31px,4vw,46px);line-height:1.1;letter-spacing:-1px;color:var(--navy);margin-bottom:13px}.section-head p{color:var(--muted);font-size:16px}
.intro-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:55px;align-items:center}.intro-text h2{font-size:40px;line-height:1.1;color:var(--navy);margin-bottom:18px}.intro-text p{color:var(--muted);font-size:17px;margin-bottom:15px}
.info-panel{background:linear-gradient(145deg,var(--navy),#07566a 58%,var(--teal));color:#fff;border-radius:28px;padding:38px;box-shadow:var(--shadow)}.info-panel h3{font-size:25px;margin-bottom:12px}.info-panel p{color:rgba(255,255,255,.78)}.check-list{list-style:none;margin-top:20px;display:grid;gap:12px}.check-list li{display:flex;gap:10px;font-weight:800}.check-list i{color:var(--mint)}
.cards,.services-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:23px}.card,.service{background:rgba(255,255,255,.9);border:1px solid rgba(6,40,74,.09);border-radius:22px;box-shadow:0 10px 35px rgba(6,40,74,.06);transition:.3s;overflow:hidden}.card{padding:30px;position:relative}.card:hover,.service:hover{transform:translateY(-7px);box-shadow:var(--shadow)}
.icon{width:54px;height:54px;border-radius:16px;background:rgba(0,143,140,.10);display:grid;place-items:center;color:var(--teal);font-size:22px;margin-bottom:18px}.card h3{color:var(--navy);font-size:20px;margin-bottom:8px}.card p,.service p{color:var(--muted)}
.service img{width:100%;height:215px;object-fit:cover;transition:.5s}.service:hover img{transform:scale(1.04)}.service-body{padding:24px;background:linear-gradient(#fff,#f6fafb)}.service-body h3{color:var(--navy);font-size:20px;margin-bottom:8px}.service-link{display:inline-block;margin-top:15px;color:var(--teal);font-weight:900}
.page-hero{padding:100px 0;text-align:center;color:#fff;background:radial-gradient(circle at 82% 30%,rgba(91,224,212,.14),transparent 38%),linear-gradient(110deg,#031b31,#07536b 65%,#087d79)}.page-hero h1{font-size:clamp(40px,5vw,60px);line-height:1.05;margin-bottom:12px}.page-hero p{font-size:18px;color:rgba(255,255,255,.84);max-width:720px;margin:auto}
.timeline{display:grid;gap:22px;max-width:900px;margin:auto}.institution{display:flex;align-items:center;gap:24px;background:rgba(255,255,255,.9);padding:28px;border-radius:20px;border-left:5px solid var(--teal);box-shadow:0 10px 35px rgba(6,40,74,.06);transition:.3s}.institution:hover{transform:translateX(6px)}.institution .icon{margin:0}.institution h3{color:var(--navy);font-size:21px}.institution p{color:var(--muted)}
.about-box{background:rgba(255,255,255,.9);border:1px solid var(--line);border-radius:25px;padding:40px;box-shadow:var(--shadow)}.about-box p{color:var(--muted);font-size:17px;margin-bottom:15px}.values{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:25px}
.contact-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:30px}.contact-info{background:linear-gradient(145deg,var(--navy),#07566a,var(--teal));color:#fff;border-radius:25px;padding:38px}.contact-info h2{font-size:32px;margin-bottom:13px}.contact-info p{color:rgba(255,255,255,.76)}.contact-item{display:flex;gap:12px;margin:20px 0}.contact-item i{color:var(--mint);font-size:20px;flex:0 0 24px;width:24px;text-align:center;line-height:1.65}.contact-item>div{min-width:0;overflow-wrap:anywhere}
.form-box{background:rgba(255,255,255,.9);border-radius:25px;padding:35px;box-shadow:var(--shadow);border:1px solid var(--line)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:12px;font-weight:900;color:var(--navy);text-transform:uppercase}.field input,.field textarea{padding:14px;border:1px solid #d5e1e8;border-radius:12px;font:inherit;outline:0}.field input:focus,.field textarea:focus{border-color:var(--teal);box-shadow:0 0 0 4px rgba(0,143,140,.08)}.form-box .btn{width:100%;margin-top:7px}
.cta{padding:72px 0;background:linear-gradient(120deg,#062b49,#07566a 55%,#078b86);color:#fff;overflow:hidden}.cta-inner{display:flex;justify-content:space-between;align-items:center;gap:30px}.cta h2{font-size:36px;line-height:1.1}.cta p{color:rgba(255,255,255,.75);margin-top:8px}
footer{background:linear-gradient(135deg,#031b31,#052c48 58%,#063f4a);color:#9bb0c1;padding:35px 0}.footer-grid{display:flex;align-items:center;justify-content:space-between;gap:30px}.footer-logo.logo-mark{width:76px;height:76px;flex-basis:76px}.footer-grid p{font-size:14px}
.wpp{position:fixed;right:24px;bottom:24px;width:62px;height:62px;border-radius:50%;background:#25d366;color:#fff;display:grid;place-items:center;font-size:29px;z-index:1100;box-shadow:0 10px 30px rgba(37,211,102,.35);transition:.25s}.wpp:hover{transform:scale(1.08)}.wpp i{font-size:29px}
.reveal{opacity:1;transform:none}.reveal.show{opacity:1;transform:none}
@media(max-width:1100px){.nav-links{position:absolute;left:15px;right:15px;top:76px;background:#fff;border-radius:18px;padding:18px;display:none;flex-direction:column;align-items:stretch;box-shadow:var(--shadow)}.nav-links.open{display:flex}.menu-btn{display:block}.intro-grid,.contact-grid{grid-template-columns:1fr}.cards,.services-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:600px){.container{width:calc(100% - 28px)}.brand .logo-mark{width:58px;height:58px;flex-basis:58px}.brand-label strong{font-size:16px}.brand-label>span{font-size:13px}.hero{min-height:620px}.hero h1{font-size:clamp(42px,12vw,58px);letter-spacing:-2px}.section{padding:70px 0}.cards,.services-grid,.form-grid,.values{grid-template-columns:1fr}.field.full{grid-column:auto}.institution{flex-direction:column;text-align:center}.institution .icon{margin:auto}.cta-inner,.footer-grid{flex-direction:column;text-align:center}.page-hero{padding:75px 0}}

.support-page{min-height:72vh;display:flex;align-items:center;padding:90px 0;background:radial-gradient(circle at 88% 20%,rgba(0,143,140,.12),transparent 35%),linear-gradient(135deg,#f7fafb,#e5f0f3);color:var(--navy)}.support-panel{max-width:760px;margin:auto;text-align:center;padding:48px;border:1px solid var(--line);border-radius:28px;background:#fff;box-shadow:0 20px 55px rgba(6,40,74,.11)}.support-icon{width:70px;height:70px;display:grid;place-items:center;margin:0 auto 20px;border-radius:19px;background:rgba(0,143,140,.10);color:var(--teal);font-size:30px}.support-panel h1{font-size:clamp(34px,4vw,50px);line-height:1.1;margin-bottom:16px}.support-panel p{font-size:18px;color:#4c6272;margin-bottom:28px}.support-panel .btn{max-width:100%}@media(max-width:600px){.support-page{padding:60px 0}.support-panel{padding:32px 22px}.support-panel .btn{font-size:14px}}

.coverage-section{background:#f6fafb}.coverage-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.coverage-card{padding:30px;background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:0 12px 35px rgba(6,40,74,.06)}.coverage-number{font-size:13px;font-weight:900;color:var(--teal);letter-spacing:2px}.coverage-card h3{font-size:21px;line-height:1.25;color:var(--navy);margin:14px 0 10px}.coverage-card p,.coverage-note{color:var(--muted)}.coverage-note{text-align:center;margin-top:26px;font-weight:700}.process-grid{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center}.process-grid h2{font-size:clamp(31px,4vw,44px);line-height:1.14;color:var(--navy);margin:10px 0 18px}.process-grid p{color:var(--muted);font-size:17px;margin-bottom:26px}.process-list{list-style:none;counter-reset:steps;display:grid;gap:17px}.process-list li{counter-increment:steps;position:relative;padding:20px 22px 20px 72px;background:#fff;border:1px solid var(--line);border-radius:18px}.process-list li:before{content:counter(steps,decimal-leading-zero);position:absolute;left:20px;top:20px;color:var(--teal);font-weight:900}.process-list strong,.process-list span{display:block}.process-list strong{color:var(--navy);margin-bottom:5px}.process-list span{color:var(--muted)}@media(max-width:900px){.coverage-grid{grid-template-columns:1fr 1fr}.process-grid{grid-template-columns:1fr;gap:35px}}@media(max-width:600px){.coverage-grid{grid-template-columns:1fr}.coverage-card{padding:25px}}

.hero{min-height:620px}.hero-content{padding:76px 0}.hero h1{font-size:clamp(43px,5.6vw,72px)}@media(max-width:600px){.hero{min-height:660px}.hero-content{padding:65px 0}}

.service-approach{background:#f6fafb}.approach-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.approach-item{padding:30px;background:#fff;border:1px solid var(--line);border-radius:20px;box-shadow:0 12px 35px rgba(6,40,74,.05)}.approach-item h3{color:var(--navy);font-size:21px;line-height:1.25;margin-bottom:12px}.approach-item p,.approach-note{color:var(--muted)}.approach-note{text-align:center;margin-top:28px}.approach-note a{color:var(--teal);font-weight:900}@media(max-width:900px){.approach-grid{grid-template-columns:1fr}}
